          '把它们混成一件事来打，是所有"绕了三天还是抓不到"的根源。</p>' +
          '<p class="small muted">对应 12.9 – 12.12、12.16。</p></div>',

          '<div class="card"><div class="card-title">缺口 ③：协议本身</div>' +
          '<p>抓到了不等于看懂了。socket 层字段溯源、Java 层与 JNI 层 SSL 的位置差异、' +
          '自编译 OpenSSL 怎么认、未知字段怎么用最少的请求确定——这些都不属于 HTTP 的范畴。</p>' +
          '<p class="small muted">对应 12.13 – 12.17。</p></div>'
