          '报文字节\n' +
          '  → 它在报文里的偏移与长度         <span class="c">（这是"这是什么"）</span>\n' +
          '  → 写入它的那个函数               <span class="c">（hook 写出口 + 调用栈回溯）</span>\n' +
          '  → 那个函数的输入                 <span class="c">（继续往上，直到找到原始来源）</span>\n' +
          '  → 输入的来源                     <span class="c">（常量表 / 时间 / 设备信息 / 上一个响应）</span>\n' +
          '  → 最终追到算法与密钥             <span class="c">（第 22、23 章的战场）</span>'
